python
def xorRegisterEvenKeyCensus(readings):
    a=readings
    out=[]
    state=0
    for x in a:
        state^=x
        out.append(state)
    return sum(x%2==0 for x in out)


java
class Solution {
  public int xorRegisterEvenKeyCensus(int[] readings) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {int state=0;for(int x:a){state^=x;out.add(state);}}
    int answer=0;for(int x:out)if(x%2==0)answer++;return answer;
  }
}
